// hooks and interceptors per client, for fast access.
type (
	hooks struct {
		Access, Archived, Audit, Deployment, Holder, Outbox, Owed, RowSeal, Site,
		Tenant, Thing []ent.Hook
	}
	inters struct {
		Access, Archived, Audit, Deployment, Holder, Outbox, Owed, RowSeal, Site,
		Tenant, Thing []ent.Interceptor
	}
)
